-- KELANA: data wisata budaya Banten, DKI Jakarta, Jawa Barat, Jawa Tengah, Jawa Timur (disetujui user 2026-11-26).
-- Sumber: docs/data/provinsi/*.json. Setiap fakta resmi membawa source_url dan checked_at.
-- cap_radius_m = 150 (keputusan user). cap_code = <kode wilayah>-NN (penomoran sementara).
-- BYPASS PEMERIKSAAN (sementara, keputusan user): fakta jam/tiket yang punya nilai dan source_url tetapi checked_at kosong diberi
-- checked_at = 2026-11-26 agar tampil di app. Itu tanggal halaman dibaca, BUKAN konfirmasi pengelola. Baris ditandai [bypass].
-- Event hanya yang cocok dengan skema events (once/weekly/daily + jam mulai); event tahunan tetap di JSON saja.
begin;

-- wilayah: buka (available) karena data sudah ada
update public.regions set status = 'available', is_sample = false where code in ('JTG','JTM','JBR');
insert into public.regions (code, name, status, sort_order, is_sample) values ('JKT','DKI Jakarta','available',11,false),('BTN','Banten','available',12,false)
on conflict (code) do update set status = 'available', name = excluded.name, is_sample = false;

-- ===== Banten =====
-- Keraton Surosowan
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'keraton-surosowan', 'Keraton Surosowan', 'lainnya'::public.place_category, 'BTN-01', 1, 150, extensions.st_setsrid(extensions.st_makepoint(106.1543798, -6.0381641), 4326)::extensions.geography, 'Jl. Masjid Agung Banten, Kecamatan Kasemen, Kota Serang, Banten', 'Reruntuhan istana pusat pemerintahan Kesultanan Banten yang berdiri di kawasan Banten Lama. Sisa denah ruang dan dinding bata yang luas masih terlihat, meski bangunan aslinya telah dihancurkan dan bahan-bahannya diambil kembali pada abad ke-19. Situs ini dikelola sebagai cagar budaya oleh Balai Pelestarian Kebudayaan Wilayah VIII.', false
from public.regions r where r.code = 'BTN'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'keraton-surosowan');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'keraton-surosowan');

-- Masjid Agung Banten
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'masjid-agung-banten', 'Masjid Agung Banten', 'lainnya'::public.place_category, 'BTN-02', 2, 150, extensions.st_setsrid(extensions.st_makepoint(106.1541066, -6.0359414), 4326)::extensions.geography, 'Kelurahan Banten, Kecamatan Kasemen, Kota Serang, Banten', 'Masjid kuno di kawasan Banten Lama yang dibangun pada abad ke-16 dan masih digunakan untuk ibadah harian. Bangunannya memadukan unsur arsitektur Jawa, Mughal, Belanda, dan Tionghoa dalam satu kompleks bersama makam para sultan Banten. Masjid ini sering dikunjungi peziarah dan wisatawan sejarah.', false
from public.regions r where r.code = 'BTN'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'masjid-agung-banten');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'masjid-agung-banten');
insert into public.ticket_prices (place_id, label, price_idr, seller_url, source_url, checked_at, review_status, is_sample) values ((select id from public.places where slug = 'masjid-agung-banten'), 'Masuk', 0, null, 'https://www.goodnewsfromindonesia.id/2026/06/19/masjid-agung-banten-akulturasi-5-budaya-dalam-salah-satu-masjid-tertua-di-nusantara', '2026-11-26T09:00:00+07', 'published', false);

-- Keraton Kaibon
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'keraton-kaibon', 'Keraton Kaibon', 'lainnya'::public.place_category, 'BTN-03', 3, 150, extensions.st_setsrid(extensions.st_makepoint(106.1600022, -6.0438351), 4326)::extensions.geography, 'Kampung Kroya, Kelurahan Kasunyatan, Kecamatan Kasemen, Kota Serang, Banten', 'Reruntuhan keraton kedua Kesultanan Banten yang dibangun sekitar 1815 untuk tempat tinggal ibu sultan. Yang tersisa berupa gerbang batu, pilar, dan sisa bangunan masjid di sisi gerbang. Situs ini ditetapkan sebagai cagar budaya di Kota Serang dan terbuka untuk dikunjungi.', false
from public.regions r where r.code = 'BTN'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'keraton-kaibon');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'keraton-kaibon');
insert into public.ticket_prices (place_id, label, price_idr, seller_url, source_url, checked_at, review_status, is_sample) values ((select id from public.places where slug = 'keraton-kaibon'), 'Masuk', 0, null, 'https://www.goodnewsfromindonesia.id/2026/06/17/keraton-kaibon-menengok-kembali-sisa-kejayaan-kesultanan-banten', '2026-11-26T09:00:00+07', 'published', false);

