-- Setu Babakan (Perkampungan Budaya Betawi)
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'setu-babakan', 'Setu Babakan (Perkampungan Budaya Betawi)', 'lainnya'::public.place_category, 'JKT-15', 15, 150, extensions.st_setsrid(extensions.st_makepoint(106.823889, -6.341667), 4326)::extensions.geography, 'Srengseng Sawah, Jagakarsa, Jakarta Selatan', 'Kawasan cagar budaya Betawi di Jagakarsa ini memiliki kampung adat, kebun warga, dan danau alami yang bisa dinikmati pengunjung. Di area ini juga ada museum Betawi, amfiteater, dan pertunjukan seni Betawi yang sering digelar di panggung terbuka.', false
from public.regions r where r.code = 'JKT'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'setu-babakan');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'setu-babakan');

