-- Museum Geologi Bandung
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'museum-geologi-bandung', 'Museum Geologi Bandung', 'museum'::public.place_category, 'JBR-06', 6, 150, extensions.st_setsrid(extensions.st_makepoint(107.620961, -6.9003424), 4326)::extensions.geography, 'Jl. Diponegoro No.57, Cihaurgeulis, Cibeunying Kaler, Kota Bandung', 'Museum Geologi di Jalan Diponegoro, Bandung, menyimpan dan memamerkan fosil, batuan, dan mineral yang dikumpulkan sejak abad ke-19. Ruang pamernya mencakup sejarah kehidupan, geologi Indonesia, dan sumber daya geologi, dengan replika fosil T-Rex dan ruang imersif. Museum ini juga berfungsi sebagai pusat dokumentasi data geologi nasional.', false
from public.regions r where r.code = 'JBR'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
