-- Museum Negeri Provinsi Jawa Barat Sri Baduga
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'museum-negeri-provinsi-jawa-barat-sri-baduga', 'Museum Negeri Provinsi Jawa Barat Sri Baduga', 'museum'::public.place_category, 'JBR-07', 7, 150, extensions.st_setsrid(extensions.st_makepoint(107.6035761, -6.9377186), 4326)::extensions.geography, 'Jalan BKR Nomor 185, Kecamatan Astanaanyar, Kota Bandung, Jawa Barat', 'Museum negeri ini menyimpan dan memamerkan benda budaya Jawa Barat, mulai dari baju adat pengantin dan mata uang masa kerajaan hingga koleksi fosil dan tengkorak. Gedung yang dulunya kantor Kawedanan Tegallega ini diresmikan sebagai museum negeri provinsi pada 1980 dan namanya mengacu pada raja Kerajaan Sunda, Sri Baduga Maharaja.', false
