select r.id, 'masjid-agung-demak', 'Masjid Agung Demak', 'lainnya'::public.place_category, 'JTG-13', 13, 150, extensions.st_setsrid(extensions.st_makepoint(110.6373455, -6.8946963), 4326)::extensions.geography, 'Kampung Kauman, Kelurahan Bintoro, Kabupaten Demak, Jawa Tengah (sekitar alun-alun kota)', 'Masjid bersejarah peninggalan Kesultanan Demak yang dikenal sebagai salah satu pusat penyebaran Islam di Jawa. Arsitekturnya memadukan unsur Islam dan tradisi Jawa, antara lain atap tumpang tiga, dan kompleksnya memiliki museum.', false
from public.regions r where r.code = 'JTG'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'masjid-agung-demak');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'masjid-agung-demak');

-- Museum R.A. Kartini
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
