-- Benteng Pendem
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'benteng-pendem', 'Benteng Pendem', 'lainnya'::public.place_category, 'JTG-16', 16, 150, extensions.st_setsrid(extensions.st_makepoint(109.0172596, -7.7491116), 4326)::extensions.geography, 'Jalan Karang, Kelurahan Cilacap, Kecamatan Cilacap, Kabupaten Cilacap, Jawa Tengah', 'Benteng Pendem adalah benteng berbentuk segi lima peninggalan Belanda di Kabupaten Cilacap, dibangun pada 1861-1879 untuk melindungi pelabuhan Cilacap. Di dalamnya masih ada barak, klinik, dan bangunan penjara, serta parit yang digali ulang. Sejak dibuka untuk umum pada 1987, benteng ini menjadi objek wisata utama di Cilacap.', false
from public.regions r where r.code = 'JTG'
