-- Candi Surowono
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'candi-surowono', 'Candi Surowono', 'candi'::public.place_category, 'JTM-05', 5, 150, extensions.st_setsrid(extensions.st_makepoint(112.2180351, -7.7464173), 4326)::extensions.geography, 'Desa Canggu, Kecamatan Badas, Kabupaten Kediri, Jawa Timur', 'Candi peninggalan era Majapahit di Desa Canggu, Kecamatan Badas, Kabupaten Kediri. Candi ini dibangun untuk memuliakan Bhre Wengker, paman Hayam Wuruk. Pengunjungnya umumnya singgah sebentar untuk melihat bangunan dan berfoto, dengan sekitar 1.000 kunjungan per bulan.', false
from public.regions r where r.code = 'JTM'
