select r.id, 'museum-keraton-sumenep', 'Museum Keraton Sumenep', 'lainnya'::public.place_category, 'JTM-18', 18, 150, extensions.st_setsrid(extensions.st_makepoint(113.8628657, -7.0083434), 4326)::extensions.geography, 'Jalan Dr. Sutomo No. 6, Pajagalan, Sumenep, Madura', 'Museum Keraton Sumenep menempati bekas pusat pemerintahan Kerajaan Sumenep di tengah kota, dengan bangunan yang didirikan sejak abad ke-18. Kompleksnya memadukan gaya arsitektur Tionghoa, Eropa, Islam, dan Jawa, dan menyimpan kereta kencana, koleksi naskah, serta Al-Quran tulisan tangan berukuran besar. Museum ini dikelola oleh UPT Museum Keraton Sumenep di bawah Pemerintah Kabupaten Sumenep.', false
from public.regions r where r.code = 'JTM'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'museum-keraton-sumenep');
